query journalpost($queryJournalpostId: String!) {
  journalpost(journalpostId: $queryJournalpostId) {
    journalpostId
    sak {
      arkivsaksnummer
      datoOpprettet
    }
    opprettetAvNavn
    journalposttype
    bruker {
      id
      type
    }
    datoOpprettet
    tittel
    journalfortAvNavn
    temanavn
    tema
    journalfoerendeEnhet
    relevanteDatoer {
      dato
      datotype
    }
    dokumenter {
      dokumentInfoId
      dokumentstatus
      tittel
      originalJournalpostId
      dokumentvarianter {
        variantformat
        filtype
      }
    }
  }
}
